assert.deepEqual(view.nodes.map((n) => [n.nodeId, n.state]), [
      ['synthesize', 'done'], ['blocked', 'blocked'], ['read-qor', 'done'], ['judge', 'done'], ['next-period', 'done'],
    ], 'the wait node keeps its place in the order the run reached it, and the retried node now says done')

assert.rejects(
      () => himaCommand(host, h.workspace, `/hima job launch LOCAL ${h.workspace} --name two -- sh ${script}`),
      (err) => {
        assert.ok(err instanceof Error, `expected an Error, got ${String(err)}`);
        assert.match(err.message, /unknown site "LOCAL"/, err.message);
        assert.match(err.message, /is the site file of "local"/, `the refusal names the Site as the Site names itself: ${err.message}`);
        return true;
      },
      'a case variant of the site name is refused as unknown, never as a second slot',
    )

assert.deepEqual(verdict.valuesAsRead, [
      { type: 'setup_wns', value: null, unit: 'ns', mode: 'setup', scope: 'all', unknownReason: 'no "WNS (ns):" row found in the setup mode timing table' },
    ])

assert.deepEqual(
      [...new Set(second.map((r) => r.type))].sort(),
      // `experience` is the Campaign's own technical report (#30), written when the Run ended, which
      // was in this generation — the ledger stamps it from the row like every other record. It is a
      // record *about the Run* rather than about this pass of the Loop, which is why the generations
      // table does not fold it in; here, where what is asserted is what the ledger stamped, it is.
      ['decision', 'experience', 'job', 'node', 'observation', 'verdict'],
      `the second generation left a node, a job, an observation, verdicts, a decision and the campaign's experience: ${JSON.stringify(second.map((r) => `${r.type}@${String(r.generation)}`))}`,
    )

assert.deepEqual(
      view.run.words,
      {
        goal: { target_period_ns: { label: 'clock period at most', unit: 'ns' } },
        strategy: { periodNs: { label: 'clock period', unit: 'ns' } },
      },
      `the run view carries the words the pack declares, resolved for this Run's pack: ${startedText}`,
    )

assert.deepEqual(explore?.parameters, {
    chooser: 'timing-push',
    bind: { guardBandNs: 0.05 },
    converge: { read: 'period', band: 0.05, generations: 1, generationLimit: 6 },
  })

assert.deepEqual(chooser.reads, {
    period: { type: 'clock_period', unit: 'ns' },
    slack: { type: 'setup_wns', unit: 'ns' },
  })

assert.rejects(
      () => himaCommand(host, h.workspace, `/hima observe LOCAL ${report.rel}`),
      (err) => {
        assert.ok(err instanceof Error, `expected an Error, got ${String(err)}`);
        assert.match(err.message, /unknown site "LOCAL"/, err.message);
        if (resolvesCaseInsensitively) {
          assert.match(err.message, /is the site file of "local"/, 'the file resolved, so the refusal names the mismatch');
          assert.match(err.message, /a Site's name is the one its file states/, err.message);
        } else {
          assert.match(err.message, /no site file at/, 'no LOCAL.yml exists on this filesystem, so this is the plain unknown-site refusal');
        }
        return true;
      },
    )

